export const runScenario = (scenario: Scenario): Result[] => {
  let previousContracts = 0;
  return scenario.steps.map((step) => {
    const premium = quote(
      {
        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
        previousContracts,
      },
      step.items ?? [],
    );
    previousContracts += 1;
    return { premium };
  });
};
